-- Free Exercise DB text data, pinned to f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5. Unlicense. Images are not imported.
WITH source_rows AS (
  SELECT * FROM jsonb_to_recordset(convert_from(decode('', 'base64'), 'UTF8')::jsonb)
  AS row_data(id text, name text, description text, primary_muscle text, secondary_muscles jsonb, equipment jsonb, difficulty text, movement_pattern text, instructions jsonb)
)
INSERT INTO public.exercise_library (id, name, description, primary_muscle, secondary_muscles, equipment, locations, difficulty, movement_pattern, instructions, recommended_sets, reps_min, reps_max, rest_seconds, alternatives, attribution, is_active)
SELECT id, name, description, primary_muscle, ARRAY(SELECT jsonb_array_elements_text(secondary_muscles)), ARRAY(SELECT jsonb_array_elements_text(equipment)), ARRAY['gym','home']::text[], difficulty, movement_pattern, ARRAY(SELECT jsonb_array_elements_text(instructions)), 3, 8, 12, 90, ARRAY[]::text[], 'Free Exercise DB (Unlicense; yuhonas/free-exercise-db)', true
FROM source_rows
ON CONFLICT (name) DO NOTHING;
